-- Copia del SQL original del usuario, commit 9751147. Solo para una base nueva y vacía.
-- Se fija UTF-8 antes de crear tablas e importar los datos.
SET NAMES utf8mb4;

CREATE DATABASE IF NOT EXISTS decanly CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE decanly;

CREATE TABLE marca (
 id_marca BIGINT PRIMARY KEY AUTO_INCREMENT,
 nombre_marca VARCHAR(80) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE imagen (
 id_imagen BIGINT PRIMARY KEY AUTO_INCREMENT,
 nombre_archivo_imagen VARCHAR(150) NOT NULL,
 tipo_mime_imagen VARCHAR(40) NOT NULL,
 contenido_imagen LONGBLOB NOT NULL,
 sha256_imagen CHAR(64) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE producto (
 id_producto BIGINT PRIMARY KEY AUTO_INCREMENT,
 marca_id_producto BIGINT NOT NULL,
 nombre_producto VARCHAR(100) NOT NULL,
 ocasion_producto VARCHAR(10) NOT NULL,
 notas_producto VARCHAR(400) NOT NULL DEFAULT '',
 imagen_id_producto BIGINT NOT NULL,
 descuento_producto INT NOT NULL DEFAULT 0,
 activo_producto BOOLEAN NOT NULL DEFAULT TRUE,
 version_producto INT NOT NULL DEFAULT 0,
 CONSTRAINT fk_producto_marca FOREIGN KEY (marca_id_producto) REFERENCES marca(id_marca),
 CONSTRAINT fk_producto_imagen FOREIGN KEY (imagen_id_producto) REFERENCES imagen(id_imagen),
 CONSTRAINT chk_producto_ocasion CHECK (ocasion_producto IN ('Día','Noche')),
 CONSTRAINT chk_producto_descuento CHECK (descuento_producto BETWEEN 0 AND 70)
) ENGINE=InnoDB;

CREATE TABLE presentacion (
 id_presentacion BIGINT PRIMARY KEY AUTO_INCREMENT,
 producto_id_presentacion BIGINT NOT NULL,
 ml_presentacion INT NOT NULL,
 precio_presentacion DECIMAL(10,2) NOT NULL,
 stock_presentacion INT NOT NULL DEFAULT 0,
 UNIQUE KEY uq_presentacion(producto_id_presentacion,ml_presentacion),
 CONSTRAINT fk_presentacion_producto FOREIGN KEY (producto_id_presentacion) REFERENCES producto(id_producto),
 CONSTRAINT chk_presentacion_ml CHECK (ml_presentacion IN (3,5,10)),
 CONSTRAINT chk_presentacion_precio CHECK (precio_presentacion>0 AND precio_presentacion<=10000),
 CONSTRAINT chk_presentacion_stock CHECK (stock_presentacion>=0)
) ENGINE=InnoDB;

CREATE TABLE producto_imagen (
 producto_id_producto_imagen BIGINT NOT NULL,
 imagen_id_producto_imagen BIGINT NOT NULL,
 descripcion_producto_imagen VARCHAR(120) NOT NULL DEFAULT '',
 orden_producto_imagen INT NOT NULL,
 PRIMARY KEY(producto_id_producto_imagen,imagen_id_producto_imagen),
 UNIQUE KEY uq_galeria_orden(producto_id_producto_imagen,orden_producto_imagen),
 CONSTRAINT fk_galeria_producto FOREIGN KEY(producto_id_producto_imagen) REFERENCES producto(id_producto),
 CONSTRAINT fk_galeria_imagen FOREIGN KEY(imagen_id_producto_imagen) REFERENCES imagen(id_imagen),
 CONSTRAINT chk_galeria_orden CHECK(orden_producto_imagen BETWEEN 0 AND 5)
) ENGINE=InnoDB;

CREATE TABLE pack (
 id_pack BIGINT PRIMARY KEY AUTO_INCREMENT,
 titulo_pack VARCHAR(60) NOT NULL,
 descripcion_pack VARCHAR(180) NOT NULL,
 etiqueta_pack VARCHAR(40) NOT NULL DEFAULT '',
 activo_pack BOOLEAN NOT NULL DEFAULT TRUE,
 version_pack INT NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE pack_detalle (
 pack_id_pack_detalle BIGINT NOT NULL,
 producto_id_pack_detalle BIGINT NOT NULL,
 ml_pack_detalle INT NOT NULL,
 cantidad_pack_detalle INT NOT NULL,
 PRIMARY KEY(pack_id_pack_detalle,producto_id_pack_detalle),
 CONSTRAINT fk_pack_detalle_pack FOREIGN KEY(pack_id_pack_detalle) REFERENCES pack(id_pack) ON DELETE CASCADE,
 CONSTRAINT fk_pack_detalle_presentacion FOREIGN KEY(producto_id_pack_detalle,ml_pack_detalle) REFERENCES presentacion(producto_id_presentacion,ml_presentacion),
 CONSTRAINT chk_pack_detalle_cantidad CHECK(cantidad_pack_detalle BETWEEN 1 AND 10)
) ENGINE=InnoDB;

CREATE TABLE configuracion (
 id_configuracion INT PRIMARY KEY,
 descuento_pack_configuracion INT NOT NULL DEFAULT 10,
 CONSTRAINT chk_configuracion_unica CHECK(id_configuracion=1),
 CONSTRAINT chk_configuracion_descuento CHECK(descuento_pack_configuracion BETWEEN 0 AND 70)
) ENGINE=InnoDB;

CREATE TABLE usuario (
  id_usuario INT AUTO_INCREMENT PRIMARY KEY,
  nombre_usuario VARCHAR(100) NOT NULL,
  correo_usuario VARCHAR(150) NOT NULL UNIQUE,
  clave_hash_usuario VARCHAR(255) NOT NULL,
  rol_usuario ENUM('ADMIN','VENDEDOR') NOT NULL DEFAULT 'ADMIN',
  activo_usuario BOOLEAN NOT NULL DEFAULT TRUE
) ENGINE=InnoDB;

CREATE TABLE pedido (
    idpedido BIGINT AUTO_INCREMENT PRIMARY KEY,
    nombrecliente VARCHAR(120) NOT NULL,
    telefono VARCHAR(20) NOT NULL,
    direccion VARCHAR(250) NOT NULL,
    fechapedido DATETIME DEFAULT CURRENT_TIMESTAMP,
    estadopedido VARCHAR(20) DEFAULT 'PENDIENTE',
    totalpedido DECIMAL(10,2) DEFAULT 0
);

CREATE TABLE detallepedido (
    iddetalle BIGINT AUTO_INCREMENT PRIMARY KEY,

    pedidoid BIGINT NOT NULL,
    productoid BIGINT NOT NULL,

    ml INT NOT NULL,
    cantidad INT NOT NULL,
    precio DECIMAL(10,2) NOT NULL,

    CONSTRAINT fk_detalle_pedido
        FOREIGN KEY (pedidoid)
        REFERENCES pedido(idpedido),

    CONSTRAINT fk_detalle_producto
        FOREIGN KEY (productoid)
        REFERENCES producto(id_producto)
);

-- Las fotografías están en la base de datos como bytes SVG autocontenidos.
USE decanly;
SET NAMES utf8mb4;
START TRANSACTION;
COMMIT;

-- Catálogo inicial heredado. Revisar precios antes de vender.
-- El stock se inicia en 0: el administrador debe ingresar el inventario real.
USE decanly;
SET NAMES utf8mb4;
START TRANSACTION;
